#[derive(PartialEq)]
enum Lookup {
    Defined,
    Missing,
    Unheld,
}

#[derive(Default)]
struct Class {
    parent: Option<String>,
    namespace: String,
    instance: HashSet<String>,
    singleton: HashSet<String>,
    includes: Vec<String>,
    extends: Vec<String>,
    open: bool,
    module: bool,
    definers: HashSet<String>,
    body_calls: HashSet<String>,
}

#[derive(Default)]
pub struct Index {
    classes: HashMap<String, Class>,
}

impl Index {
    pub fn of(files: &[(String, String)]) -> Self {
        let mut index = Index::default();
        for (path, text) in files {
            if !path.ends_with(".rb") {
                continue;
            }
            let parsed = ruby_prism::parse(text.as_bytes());
            index.walk_body(Some(parsed.node()), "", false);
        }
        index
    }

    fn entry(&mut self, name: &str, namespace: &str) -> &mut Class {
        let class = self.classes.entry(name.to_string()).or_default();
        class.namespace = namespace.to_string();
        class
    }

    fn walk_body(&mut self, node: Option<ruby_prism::Node<'_>>, owner: &str, singleton: bool) {
        let Some(node) = node else { return };
        let stmts: Vec<ruby_prism::Node<'_>> = if let Some(p) = node.as_program_node() {
            p.statements().body().iter().collect()
        } else if let Some(s) = node.as_statements_node() {
            s.body().iter().collect()
        } else {
            vec![node]
        };
        for stmt in stmts {
            self.statement(stmt, owner, singleton);
        }
    }

    fn statement(&mut self, stmt: ruby_prism::Node<'_>, owner: &str, singleton: bool) {
        if let Some(class) = stmt.as_class_node() {
            let name = qualify(owner, &const_name(&class.constant_path()));
            let parent = class.superclass().map(|s| match const_text(&s) {
                Some(text) => text,
                None => String::from("?"),
            });
            let entry = self.entry(&name, owner);
            if let Some(p) = parent {
                entry.parent = Some(p);
            }
            self.walk_body(class.body(), &name, false);
        } else if let Some(module) = stmt.as_module_node() {
            let name = qualify(owner, &const_name(&module.constant_path()));
            self.entry(&name, owner).module = true;
            self.walk_body(module.body(), &name, false);
        } else if let Some(sclass) = stmt.as_singleton_class_node() {
            if sclass.expression().as_self_node().is_some() {
                self.walk_body(sclass.body(), owner, true);
            }
        } else if let Some(def) = stmt.as_def_node() {
            let name = String::from_utf8_lossy(def.name().as_slice()).to_string();
            let on_self = singleton || def.receiver().is_some_and(|r| r.as_self_node().is_some());
            let class = self.classes.entry(owner.to_string()).or_default();
            if name == "method_missing" {
                class.open = true;
            }
            if def.body().is_some_and(|b| defines_at_runtime(&b)) {
                class.definers.insert(name.clone());
            }
            if on_self { class.singleton.insert(name); } else { class.instance.insert(name); }
        } else if let Some(alias) = stmt.as_alias_method_node() {
            if let Some(sym) = alias.new_name().as_symbol_node() {
                let name = String::from_utf8_lossy(sym.unescaped()).to_string();
                let class = self.classes.entry(owner.to_string()).or_default();
                if singleton { class.singleton.insert(name); } else { class.instance.insert(name); }
            }
        } else if let Some(call) = stmt.as_call_node() {
            if call.block().is_some() && defines_at_runtime(&stmt) {
                self.classes.entry(owner.to_string()).or_default().open = true;
                return;
            }
            if call.receiver().is_some() {
                return;
            }
            let method = String::from_utf8_lossy(call.name().as_slice()).to_string();
            self.classes.entry(owner.to_string()).or_default().body_calls.insert(method.clone());
            let args: Vec<ruby_prism::Node<'_>> = call.arguments().map(|a| a.arguments().iter().collect()).unwrap_or_default();
            let class = self.classes.entry(owner.to_string()).or_default();
            let names = || args.iter().filter_map(|a| a.as_symbol_node().map(|s| String::from_utf8_lossy(s.unescaped()).to_string())).collect::<Vec<_>>();
            fn side(class: &mut Class, singleton: bool) -> &mut HashSet<String> {
                if singleton { &mut class.singleton } else { &mut class.instance }
            }
            match method.as_str() {
                "attr_reader" => side(class, singleton).extend(names()),
                "attr_writer" => side(class, singleton).extend(names().into_iter().map(|n| format!("{n}="))),
                "attr_accessor" => {
                    for n in names() {
                        side(class, singleton).insert(format!("{n}="));
                        side(class, singleton).insert(n);
                    }
                }
                "alias_method" | "define_method" => {
                    if let Some(n) = names().into_iter().next() {
                        side(class, singleton).insert(n);
                    } else {
                        class.open = true;
                    }
                }
                "define_singleton_method" => class.open = true,
                "include" | "prepend" => class.includes.extend(args.iter().filter_map(const_text)),
                "extend" => class.extends.extend(args.iter().filter_map(const_text)),
                "module_function" if args.is_empty() => {}
                _ => {}
            }
        } else if let Some(begin) = stmt.as_begin_node() {
            self.walk_body(begin.statements().map(|s| s.as_node()), owner, singleton);
        } else if let Some(i) = stmt.as_if_node() {
            self.walk_body(i.statements().map(|s| s.as_node()), owner, singleton);
        }
    }

    fn is_module(&self, class: &str) -> bool {
        self.classes.get(class).is_some_and(|c| c.module)
    }

    fn emits(&self, class: &str, name: &str, class_side: bool) -> bool {
        self.classes.get(class).is_some_and(|c| if class_side { c.singleton.contains(name) } else { c.instance.contains(name) })
    }

    fn resolve<'a>(&'a self, name: &str, namespace: &str) -> Option<(&'a str, &'a Class)> {
        let name = name.trim_start_matches("::");
        let mut ns = namespace.to_string();
        loop {
            let candidate = qualify(&ns, name);
            if let Some((key, class)) = self.classes.get_key_value(&candidate) {
                return Some((key.as_str(), class));
            }
            match ns.rfind("::") {
                Some(i) => ns.truncate(i),
                None if !ns.is_empty() => ns.clear(),
                None => return None,
            }
        }
    }

    fn defines(&self, class: &str, name: &str, class_side: bool) -> Lookup {
        let mut seen = HashSet::new();
        self.lookup(class, "", name, class_side, &mut seen)
    }

    fn lookup(&self, class: &str, namespace: &str, name: &str, class_side: bool, seen: &mut HashSet<String>) -> Lookup {
        let Some((key, info)) = self.resolve(class, namespace) else { return Lookup::Unheld };
        // Not the tree's reopen alone: `class Time` adds to Ruby's own class, whose methods it does not list.
        if !seen.insert(key.to_string()) || info.open || (info.parent.is_none() && CORE_CONSTANTS.contains(&key)) {
            return Lookup::Unheld;
        }
        let own = if class_side { &info.singleton } else { &info.instance };
        if own.contains(name) {
            return Lookup::Defined;
        }
        let mods = if class_side { &info.extends } else { &info.includes };
        // Not any mixin that can define methods: only one whose definer the emitted body calls (`monetize :amount`) has run.
        let ran = |c: &Class| c.open || c.definers.iter().any(|d| info.body_calls.contains(d));
        if ran(info) || info.includes.iter().chain(info.extends.iter()).any(|m| self.resolve(m, &info.namespace).is_some_and(|(_, c)| ran(c))) {
            return Lookup::Unheld;
        }
        // Not only `extend`: a module the tree does not hold may add class methods from its `included` hook (`Singleton#instance`).
        let mut unknown = class_side
            && info.includes.iter().any(|m| {
                let name = m.trim_start_matches("::");
                match self.resolve(m, &info.namespace) {
                    Some((_, held)) => held.singleton.contains("included") || held.singleton.contains("prepended"),
                    None => name == "Singleton" || !CORE_CONSTANTS.contains(&name),
                }
            });
        for m in mods {
            match self.lookup(m, &info.namespace, name, false, seen) {
                Lookup::Defined => return Lookup::Defined,
                Lookup::Unheld => unknown = true,
                Lookup::Missing => {}
            }
        }
        match info.parent.as_deref() {
            Some("?") => return Lookup::Unheld,
            Some(parent) => match self.lookup(parent, &info.namespace, name, class_side, seen) {
                Lookup::Defined => return Lookup::Defined,
                Lookup::Unheld => unknown = true,
                Lookup::Missing => {}
            },
            None => {
                let builtin = if class_side { CLASS_METHODS } else { OBJECT_METHODS };
                if builtin.contains(&name) {
                    return Lookup::Defined;
                }
            }
        }
        if unknown { Lookup::Unheld } else { Lookup::Missing }
    }
}

fn defines_at_runtime(node: &ruby_prism::Node<'_>) -> bool {
    struct Finder(bool);
    impl<'pr> ruby_prism::Visit<'pr> for Finder {
        fn visit_call_node(&mut self, node: &ruby_prism::CallNode<'pr>) {
            if matches!(
                node.name().as_slice(),
                b"define_method" | b"define_singleton_method" | b"attr_accessor" | b"attr_reader" | b"attr_writer" | b"alias_method" | b"class_eval" | b"instance_eval" | b"module_eval"
            ) {
                self.0 = true;
            }
            ruby_prism::visit_call_node(self, node);
        }
    }
    let mut finder = Finder(false);
    ruby_prism::Visit::visit(&mut finder, node);
    finder.0
}

fn qualify(owner: &str, name: &str) -> String {
    if owner.is_empty() || name.starts_with("::") { name.trim_start_matches("::").to_string() } else { format!("{owner}::{name}") }
}

fn const_name(node: &ruby_prism::Node<'_>) -> String {
    const_text(node).unwrap_or_default()
}

fn const_text(node: &ruby_prism::Node<'_>) -> Option<String> {
    if let Some(c) = node.as_constant_read_node() {
        return Some(String::from_utf8_lossy(c.name().as_slice()).to_string());
    }
    let path = node.as_constant_path_node()?;
    let name = String::from_utf8_lossy(path.name()?.as_slice()).to_string();
    match path.parent() {
        Some(parent) => Some(format!("{}::{name}", const_text(&parent)?)),
        None => Some(format!("::{name}")),
    }
}

pub fn audit(classes: &[crate::dialect::LibraryClass], files: &[(String, String)]) -> Vec<Diagnostic> {
    let index = Index::of(files);
    let mut out = Vec::new();
    let mut seen = HashSet::new();
    for lc in classes {
        for m in &lc.methods {
            let class_side = m.receiver == crate::dialect::MethodReceiver::Class;
            // Not every rendered method: the tree shake drops the unused ones, and their calls never run.
            if !index.emits(lc.name.0.as_str(), m.name.as_str(), class_side) {
                continue;
            }
            walk(&m.body, Some((lc.name.0.as_str(), class_side)), &index, &mut out, &mut seen);
        }
    }
    out
}

fn walk(expr: &Expr, owner: Option<(&str, bool)>, index: &Index, out: &mut Vec<Diagnostic>, seen: &mut HashSet<(crate::span::Span, String, bool, String)>) {
    if let ExprNode::Send { recv, method, .. } = &*expr.node
        && expr.diagnostic().is_none()
    {
        // Not a module's own `self`: a concern's body runs on its includer, whose methods it calls.
        let own = owner.filter(|(c, _)| !index.is_module(c)).map(|(c, side)| (c.to_string(), side));
        let target = match recv {
            None => own,
            Some(r) if matches!(&*r.node, ExprNode::SelfRef) => own,
            Some(r) => match &r.ty {
                Some(Ty::Class { id, .. }) => {
                    let class_side = match &*r.node {
                        ExprNode::Const { .. } => true,
                        ExprNode::Send { method, args, .. } => method.as_str() == "class" && args.is_empty(),
                        _ => false,
                    };
                    Some((id.0.as_str().to_string(), class_side))
                }
                _ => None,
            },
        };
        if let Some((class, class_side)) = target
            && index.defines(&class, method.as_str(), class_side) == Lookup::Missing
            && seen.insert((expr.span, class.clone(), class_side, method.as_str().to_string()))
        {
            out.push(Diagnostic {
                span: expr.span,
                severity: crate::diagnostic::Severity::Warning,
                kind: crate::diagnostic::DiagnosticKind::SendDispatchFailed {
                    method: method.clone(),
                    recv_ty: Ty::Class { id: crate::ident::ClassId(crate::ident::Symbol::from(class.as_str())), args: vec![].into() },
                },
                message: format!(
                    "`{}{}{}` is called, but the emitted Ruby defines no such method",
                    class,
                    if class_side { "." } else { "#" },
                    method.as_str()
                ),
            });
        }
    }
    expr.node.for_each_child(&mut |child| walk(child, owner, index, out, seen));
}

#[cfg(test)]
mod tests {
    fn findings(src: &str) -> Vec<String> {
        let classes = crate::ingest::ingest_library_classes(src.as_bytes(), "a.rb").expect("ingest");
        super::audit(&classes, &[("a.rb".to_string(), src.to_string())]).into_iter().map(|d| d.message).collect()
    }

    #[test]
    fn an_undefined_implicit_send_is_reported() {
        let found = findings("class A\n  def x\n    y\n  end\nend\n");
        assert!(found.iter().any(|m| m.contains("`A#y`")), "{found:?}");
    }

    #[test]
    fn a_defined_or_inherited_method_is_not() {
        let found = findings("class B\n  def y\n    1\n  end\nend\n\nclass A < B\n  def x\n    y.to_s + to_s\n  end\nend\n");
        assert!(found.is_empty(), "{found:?}");
    }

    #[test]
    fn a_reopened_core_class_is_not_audited() {
        let found = findings("class Time\n  def x\n    y\n  end\nend\n");
        assert!(found.is_empty(), "{found:?}");
    }

    #[test]
    fn a_held_mixin_with_an_included_hook_leaves_the_class_side_unknown() {
        let found = findings("module M\n  def self.included(base)\n    base.extend(Helpers)\n  end\nend\n\nclass A\n  include M\n\n  def self.x\n    y\n  end\nend\n");
        assert!(found.is_empty(), "{found:?}");
    }

    #[test]
    fn each_class_s_missing_method_is_reported_once() {
        let found = findings("class A\n  def x\n    y\n  end\nend\n\nclass B\n  def x\n    y\n  end\nend\n");
        assert!(found.iter().any(|m| m.contains("`A#y`")) && found.iter().any(|m| m.contains("`B#y`")), "{found:?}");
    }

    #[test]
    fn a_definer_opens_a_class_only_when_its_body_calls_it() {
        let module = "module M\n  def setting(name)\n    define_method(name) { 1 }\n  end\nend\n\n";
        let called = findings(&format!("{module}class A\n  extend M\n  setting :y\n\n  def x\n    y\n  end\nend\n"));
        assert!(called.is_empty(), "{called:?}");
        let uncalled = findings(&format!("{module}class A\n  extend M\n\n  def x\n    y\n  end\nend\n"));
        assert!(uncalled.iter().any(|m| m.contains("`A#y`")), "{uncalled:?}");
    }
}
